SELECT COUNT(DISTINCT c.uuid) AS total_cards_with_no_or_variable_power
FROM cards c
WHERE c.power IS NULL OR c.power LIKE '%*%';

SELECT ROUND((
  (SELECT overall_rating FROM Player_Attributes WHERE player_api_id = (SELECT player_api_id FROM Player WHERE player_name = 'Landon Donovan') AND date <= '2013-07-12' ORDER BY date DESC LIMIT 1) -
  (SELECT AVG(overall_rating) FROM Player_Attributes WHERE date <= '2013-07-12' AND defensive_work_rate IN ('low', 'medium', 'high'))
) * 100.0 / (SELECT AVG(overall_rating) FROM Player_Attributes WHERE date <= '2013-07-12' AND defensive_work_rate IN ('low', 'medium', 'high')), 2) AS percentage_higher;

