SELECT DISTINCT disp.account_id
FROM disp
JOIN card ON disp.disp_id = card.disp_id;

SELECT major_name
FROM major
WHERE college = 'College of Engineering';

SELECT expense_date, cost
FROM expense
WHERE expense_date = '2019-11-19';

SELECT COUNT(*) AS carcinogenic_molecule_count
FROM molecule
WHERE label = '+';

SELECT ROUND(COUNT(CASE WHEN element = 'cl' THEN 1 END) * 1.0 / COUNT(*), 4) AS percentage_chlorine_atoms
FROM atom
WHERE molecule_id IN (SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '-');

